    const h = await (await fetch("/health")).json();
    const ok = h.status === "ok" && h.llm_configured;
    $("status-dot").className = "dot " + (ok ? "ok" : "bad");
    const b = h.budget;
    $("status-text").textContent = ok ? `Online · $${fmt(b.remaining_usd, 2)} budget left today` : "AI service unavailable";
    $("status").title = `Model ${h.llm_model} · scores ${h.scoring_version} · computed ${h.scores_computed_at}`;
    return h;
  } catch {
    $("status-dot").className = "dot bad"; $("status-text").textContent = "Offline"; return null;
  }
}
