    $("mic").hidden = false;
    $("mic").addEventListener("click", () => (rec ? rec.stop() : startListening()));
  }
  if (canSpeak) {
    $("speak-toggle").hidden = false;
    $("speak-toggle").addEventListener("click", () => setAutoSpeak(!state.speak));
    setAutoSpeak(state.speak);
