// Runs in the page. Replaces the browser speech APIs with fakes and checks the voice flows.
const results = {};
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const mic = document.getElementById("mic"), input = document.getElementById("input"), hint = document.getElementById("composer-hint");

// Fake speech recognition
let last = null;
class FakeRec { constructor() { last = this; this.started = false; this.aborted = false; }
  start() { this.started = true; } stop() { this.onend && this.onend(); } abort() { this.aborted = true; this.onerror && this.onerror({ error: "aborted" }); this.onend && this.onend(); } }
const say = (rec, ...pieces) => rec.onresult({ results: pieces.map((p) => [{ transcript: p }]) });
window.SpeechRecognition = FakeRec;

// 1. Speak a question: interim then final text fills the box; nothing is sent
input.value = "";
mic.click();
results.listening = mic.classList.contains("listening") && mic.getAttribute("aria-pressed") === "true" && last.started && /Listening/.test(hint.textContent);
say(last, "Which Midwest hubs");
results.interim = input.value;
say(last, "Which Midwest hubs", " are most exposed to winter disruption");
mic.click(); // stop -> onend
results.final = input.value;
results.stopped = !mic.classList.contains("listening") && /Check the text/.test(hint.textContent);
results.notSent = document.getElementById("thread").children.length === 0;

// 2. Speaking again appends to existing text
mic.click(); say(last, "in December"); last.stop();
results.appended = input.value;

// 3. Errors show a plain message
mic.click(); const r3 = last; r3.onerror({ error: "not-allowed" }); r3.onend();
results.errorHint = hint.textContent; results.errorClass = hint.classList.contains("hint-error");
mic.click(); const r4 = last; r4.onerror({ error: "no-speech" }); r4.onend();
results.noSpeechHint = hint.textContent;

// 4. Sending while listening stops recognition and late results are ignored
input.value = "";
mic.click(); const r5 = last; say(r5, "test");
const fakeAsk = { sent: null };
window.__origFetch = window.__origFetch || window.fetch;
window.fetch = async (url, opts) => { if (String(url).includes("/api/chat") && !String(url).includes("reset")) { fakeAsk.sent = JSON.parse(opts.body).message;
  return new Response(JSON.stringify({ session_id: "s1", answer: { answer_markdown: "**Fargo** ranks first with 1.91 disaster-level days/yr.\n\n| Hub | Days |\n|---|---|\n| Fargo | 1.91 |\n| Wichita | 2.27 |\n\n- Winter is the main driver\n- Range 1.03 to 1.75", question_type: "ranking", measure_used: "severe_disruption_days", uncertainty: { level: "low", reasons: [] }, suggested_followups: [], awaiting_user_confirmation: false, assumptions: [] }, figures: [], data_sources: [], validation_warnings: [], tool_trace: [], usage: {}, latency_s: 1 }), { status: 200, headers: { "Content-Type": "application/json" } }); }
  return window.__origFetch(url, opts); };

// Fake speech synthesis
const spoken = []; let cancels = 0;
Object.defineProperty(window, "speechSynthesis", { configurable: true, value: { speak: (u) => spoken.push(u), cancel: () => { cancels++; }, getVoices: () => [] } });

document.getElementById("composer").requestSubmit();
results.abortedOnSend = r5.aborted && !mic.classList.contains("listening");
say(r5, "late text"); results.lateIgnored = input.value === "";
await wait(400);
results.sentText = fakeAsk.sent;

// 5. Auto read-aloud off by default: nothing spoken
results.spokenWhenOff = spoken.length;

// 6. Per-answer read button speaks clean text
const card = document.querySelector(".msg-ai");
const btn = card.querySelector(".read-btn");
btn.click();
results.spokenText = spoken.map((u) => u.text).join(" | ");
results.readBtnOn = btn.classList.contains("on");
results.noMarkdown = !/[*|#]/.test(results.spokenText);
btn.click(); results.readBtnOffAfterStop = !btn.classList.contains("on");
spoken.length = 0;

// 7. Toggle on: next answer is read automatically; new question stops reading
const tog = document.getElementById("speak-toggle");
tog.click(); results.toggleOn = tog.getAttribute("aria-pressed") === "true" && localStorage.getItem("wra_speak") === "1";
input.value = "Second question"; document.getElementById("composer").requestSubmit();
await wait(400);
results.autoSpoken = spoken.length > 0;
const c0 = cancels; input.value = "Third question"; document.getElementById("composer").requestSubmit();
results.cancelOnNewQuestion = cancels > c0;
await wait(400);
tog.click(); results.toggleOff = tog.getAttribute("aria-pressed") === "false";

// 8. New chat stops reading
const c1 = cancels; document.getElementById("new-chat").click(); await wait(100);
results.cancelOnNewChat = cancels > c1;

window.fetch = window.__origFetch;
results;

