51 if (v == null || v === false) continue;
52 if (k === "class") n.className = v;
53 else if (k === "html") n.innerHTML = v; // only used with static, trusted SVG strings
54 else if (k.startsWith("on")) n.addEventListener(k.slice(2), v);
55 else if (k === "style") n.setAttribute("style", v);
56 else n.setAttribute(k, v === true ? "" : v);
57 }
58 for (const c of children.flat()) if (c != null && c !== false) n.append(c instanceof Node ? c : String(c));
59 return n;
60 }
