62 function fill(node, ...kids) { node.replaceChildren(...kids.flat().filter((k) => k != null && k !== false)); }
63 const fmt = (v, d = 2) => (v == null ? "n/a" : Number(v).toLocaleString(undefined, { maximumFractionDigits: d, minimumFractionDigits: 0 }));
64 /* 0.36 -> "once every 2.8 yrs"; 1.4 -> "1.4 days/yr". */
65 function oncePer(v) {
66 if (!v) return "none in the data";
