def run_check(conn: sqlite3.Connection, fetch: Callable[[float, float], list[dict]] = fetch_active,
              post: Callable[[str, dict], None] = post_webhook, webhook_url: str | None = None,
              checked_at: str | None = None) -> dict:
    """Check every hub once, record what changed, send the webhook, and return a summary.

    fetch and post are parameters so tests can replace the network with recorded responses.
    """
    if not _RUN_LOCK.acquire(blocking=False):
        return {"skipped": "a check is already running"}
    try:
        return _run_check(conn, fetch, post, webhook_url, checked_at or now_iso())

