"""Count occurrences of secrets and personal details in the exported files, without printing any value."""
import re
import sys
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8")
root = Path(sys.argv[1])
env = {}
for line in open("C:/Users/97254/Downloads/Moveo_Assignment/weather-risk-agent/.env", encoding="utf-8"):
    m = re.match(r"^\s*([A-Z_]+)\s*=\s*(.*?)\s*$", line)
    if m and m.group(2):
        env[m.group(1)] = m.group(2).strip("'\"")
needles = {k: env[k] for k in ("OPENAI_API_KEY", "APP_ACCESS_CODE", "ADMIN_TOKEN") if k in env}
needles["user email"] = "[email removed]"
for f in sorted(p for p in root.rglob("*") if p.suffix in (".jsonl", ".json", ".txt", ".md")):
    text = f.read_text(encoding="utf-8", errors="replace")
    hits = {name: text.lower().count(value.lower()) for name, value in needles.items()}
    keylike = len(re.findall(r"sk-[A-Za-z0-9_-]{20,}", text))
    found = {k: v for k, v in hits.items() if v}
    if found or keylike:
        print(f.relative_to(root), found, "key-like:", keylike)
print("scan done over", sum(1 for _ in root.rglob("*")), "paths")

